function draw(ctx, size) {
  ctx.imageSmoothingEnabled = false;
  const px = (x, y, w, h, c) => { ctx.fillStyle = c; ctx.fillRect(x|0, y|0, w|0, h|0); };
  const O = '#051428', Wood = '#8b5a2b', WoodLt = '#c48a4a', WoodDk = '#5a3a18';
  const Metal = '#9aa3ad', Eye = '#ff3030', Glow = '#f4c020', Shine = '#fff8ea';

  // alert rays
  px(2, 4, 2, 2, Glow); px(28, 4, 2, 2, Glow);
  px(1, 12, 2, 2, Glow); px(29, 12, 2, 2, Glow);
  px(4, 2, 2, 1, Eye); px(26, 2, 2, 1, Eye);

  // crate (lid ajar — shifted)
  px(5, 9, 20, 19, O);
  px(6, 10, 18, 17, Wood);
  px(6, 10, 18, 2, WoodLt);
  px(6, 25, 18, 2, WoodDk);
  px(6, 10, 1, 17, WoodLt);
  px(23, 10, 1, 17, WoodDk);
  for (let i = 0; i < 16; i++) {
    px(7 + i, 11 + Math.floor(i * 14 / 15), 1, 2, WoodDk);
    px(22 - i, 11 + Math.floor(i * 14 / 15), 1, 2, WoodDk);
  }
  // open lid top
  px(8, 4, 16, 6, O);
  px(9, 5, 14, 4, WoodLt);
  px(9, 5, 14, 1, Glow);
  // big eye
  px(12, 13, 8, 7, O);
  px(13, 14, 6, 5, Eye);
  px(14, 15, 2, 2, Shine);
  px(17, 16, 1, 1, Shine);
  // broken lock
  px(13, 21, 3, 3, Metal);
  px(16, 22, 3, 1, Metal);
}
